  const TOOLS={basics:{id:'basics',name:'BASiCS',url:'https://bioconductor.org/packages/release/bioc/vignettes/BASiCS/inst/doc/BASiCS.html'},brms:{id:'brms',name:'brms',url:'https://paulbuerkner.com/brms/articles/brms_phylogenetics.html'},mcmc:{name:'MCMCglmm',url:'https://cran.r-project.org/package=MCMCglmm'},stan:{name:'Stan / posterior',url:'https://mc-stan.org/learn-stan/diagnostics-warnings.html'},sbc:{name:'SBC',url:'https://hyunjimoon.github.io/SBC/'},phytools:{id:'phytools2',name:'phytools 2',url:'https://search.r-project.org/CRAN/refmans/phytools/html/phylosig.html'},ancestors:{id:'phytools2',name:'phytools 2 · fastAnc',url:'https://search.r-project.org/CRAN/refmans/phytools/html/fastAnc.html'},mvmorph:{name:'mvMORPH',url:'https://github.com/JClavel/mvMORPH'},iqtree:{name:'IQ-TREE 3',url:'https://iqtree.github.io/doc/Home'},raxml:{name:'RAxML-NG',url:'https://github.com/amkozlov/raxml-ng/wiki'},beast:{name:'BEAST 2',url:'https://www.beast2.org/tutorials/'},revbayes:{name:'RevBayes',url:'https://revbayes.github.io/tutorials/'},ggtree:{name:'ggtree',url:'https://yulab-smu.top/treedata-book/'},ete:{name:'ETE 4',url:'https://etetoolkit.github.io/ete/'},slim:{name:'SLiM 5',url:'https://messerlab.org/slim/'},msprime:{name:'msprime',url:'https://tskit.dev/msprime/docs/stable/'}};
  const RAW=[
    ['bayes_noise','posterior','rna',L('贝叶斯均值—噪音估计','Bayesian mean–noise estimation','Estimation bayésienne moyenne–bruit','Estimación bayesiana media–ruido','Batezbesteko–zarata estimazio bayestarra'),L('哪些表达变异超出均值依赖，估计有多确定？','Which variation exceeds mean dependence, and how certain is the estimate?','Quelle variabilité dépasse la dépendance à la moyenne, et avec quelle incertitude ?','¿Qué variabilidad supera la dependencia de la media y con qué incertidumbre?','Zein aldakortasun dago batezbestekoaren mendekotasunetik harago, eta zer ziurgabetasun du?'),['counts','design','technical'],['posterior'],['basics'],['basics','basicsCorrection'],['mean_noise','noise_likelihood_calibration'],L('先确认 spike-in 或真实技术重复分支。随机拆分细胞不是技术重复；残余过度离散不等于内在噪音或转录速率。','Confirm the spike-in or genuine technical-replicate branch. Random cell splits are not technical replicates; residual overdispersion is not intrinsic noise or a transcription rate.','Vérifiez la branche spike-in ou réplicats techniques réels. Une division aléatoire des cellules ne crée pas de réplicats ; la surdispersion résiduelle n’est ni un bruit intrinsèque ni un taux de transcription.','Confirme la vía con spike-ins o réplicas técnicas reales. Dividir células al azar no crea réplicas; la sobredispersión residual no es ruido intrínseco ni tasa de transcripción.','Egiaztatu spike-in edo benetako erreplika teknikoen adarra. Zelulak ausaz banatzea ez da erreplikazio teknikoa; hondar-gaindispertsioa ez da berezko zarata edo transkripzio-tasa.')],
    ['measurement_error','posterior','rna',L('噪音估计误差的传播','Propagating noise-estimation error','Propagation de l’erreur d’estimation du bruit','Propagación del error de estimación del ruido','Zarata-estimazioaren errorea hedatzea'),L('菌株差异是否超过各自噪音估计的不确定性？','Do strain differences exceed uncertainty in their noise estimates?','Les différences entre souches dépassent-elles l’incertitude des estimations ?','¿Superan las diferencias entre cepas la incertidumbre de sus estimaciones?','Anduien arteko aldeak estimazioen ziurgabetasuna baino handiagoak al dira?'),['traits','design','priors'],['error'],['brms','mcmc'],['brms','ives'],['noise_components','noise_power'],L('brms se() 接收同尺度抽样标准误，MCMCglmm mev 接收方差。后验标准差不能机械替代抽样标准误，也不能把后验直接再当似然。','brms se() takes sampling standard errors on the response scale; MCMCglmm mev takes variances. Posterior SD is not automatically a sampling SE, and a posterior cannot simply be reused as a likelihood.','brms se() reçoit une erreur-type d’échantillonnage sur l’échelle de réponse ; mev de MCMCglmm reçoit une variance. L’écart-type postérieur n’est pas automatiquement une erreur-type, et un postérieur ne remplace pas une vraisemblance.','brms se() recibe errores estándar de muestreo en la escala de respuesta; mev de MCMCglmm recibe varianzas. La DE posterior no sustituye automáticamente al error estándar ni la posterior a una verosimilitud.','brms se() funtzioak erantzun-eskalako laginketa-errore estandarrak hartzen ditu; MCMCglmm mev-k bariantzak. Desbideratze posteriorra ez da automatikoki laginketa-errorea, eta posteriorra ezin da besterik gabe egiantzekotasun bihurtu.')],
    ['posterior_checks','posterior','model',L('后验计算与模型检验','Posterior computation and model checks','Calcul postérieur et validation du modèle','Cálculo posterior y controles del modelo','Kalkulu posteriorra eta eredu-egiaztapenak'),L('后验计算可靠吗，模型预测能复现观测数据吗？','Is posterior computation reliable, and do model predictions reproduce the observations?','Le calcul postérieur est-il fiable et les prédictions du modèle reproduisent-elles les observations ?','¿Es fiable el cálculo posterior y reproducen las predicciones del modelo las observaciones?','Kalkulu posteriorra fidagarria al da, eta ereduaren iragarpenek behaketak erreproduzitzen al dituzte?'),['draws','priors','generativeChecks'],['diagnostics'],['stan','sbc'],['diagnostics','sbc'],['noise_likelihood_calibration','mechanistic_noise_benchmark'],L('收敛诊断、后验预测和 SBC 分别检查计算、数据适配和模拟校准。HMC divergence 仅用于相应采样器；任一项通过都不单独证明机制。','Convergence diagnostics, posterior prediction and SBC assess computation, data fit and simulation calibration respectively. HMC divergences apply only to the relevant sampler; no single check establishes a mechanism.','Les diagnostics, la prédiction postérieure et SBC évaluent respectivement calcul, ajustement et calibration simulée. Les divergences HMC concernent cet échantillonneur ; aucun contrôle ne démontre seul un mécanisme.','Los diagnósticos, la predicción posterior y SBC evalúan cálculo, ajuste y calibración simulada. Las divergencias HMC corresponden a ese muestreador; ningún control aislado demuestra un mecanismo.','Diagnostikoek, iragarpen posteriorrak eta SBCk kalkulua, doikuntza eta simulazio-kalibrazioa aztertzen dituzte. HMC dibergentziak dagokion laginketarako dira; egiaztapen bakarrak ez du mekanismorik frogatzen.')],
    ['genomic_variance','heritability','kinship_required',L('K 矩阵与加性遗传方差','Genomic K and additive variance','Matrice K et variance additive','Matriz K y varianza aditiva','K genomikoa eta bariantza gehigarria'),L('条件化噪音的菌株差异有多少与基因型亲缘一致？','How much strain variation in conditional noise follows genomic relatedness?','Quelle part de la variation du bruit conditionnel suit la parenté génomique ?','¿Qué parte de la variación del ruido condicional sigue el parentesco genómico?','Baldintzapeko zarataren andui-aldakortasunak zenbateraino jarraitzen du ahaidetasun genomikoa?'),['traits','design','covariance','covariates'],['h2'],['brms','mcmc'],['brms','mcmc','boocock'],['noise_qtl','shared_genetic_architecture'],L('在指定 K、性状尺度与设计下估计加性方差比例。独立培养与菌株效应需可区分；细胞数量不能替代独立基因型数量。','Estimate the additive variance fraction for a specified K, trait scale and design. Culture and strain effects must be separable; cell counts do not replace independent genotypes.','Estimez la proportion additive pour K, l’échelle et le plan spécifiés. Les effets culture et souche doivent être séparables ; les cellules ne remplacent pas les génotypes indépendants.','Estime la proporción aditiva para K, escala y diseño especificados. Los efectos de cultivo y cepa deben ser separables; las células no sustituyen a genotipos independientes.','Estimatu proportzio gehigarria zehaztutako K, eskala eta diseinurako. Kultibo- eta andui-efektuek bereizgarriak izan behar dute; zelulek ez dituzte genotipo independenteak ordezkatzen.')],
    ['tree_variance','heritability','tree_required',L('树协方差与系统发育方差','Tree covariance and phylogenetic variance','Covariance de l’arbre et variance phylogénétique','Covarianza del árbol y varianza filogenética','Zuhaitz-kobariantza eta bariantza filogenetikoa'),L('共享遗传历史能解释哪些噪音或状态差异？','Which noise or state differences follow shared evolutionary history?','Quelles différences de bruit ou d’état suivent l’histoire évolutive commune ?','¿Qué diferencias de ruido o estado siguen la historia evolutiva compartida?','Zein zarata- edo egoera-aldek jarraitzen diote historia ebolutibo partekatuari?'),['traits','tree','design','covariates'],['phyvariance'],['brms','mcmc'],['brms','mcmc','peter'],['evolution_context'],L('树协方差 C 的方差比例与基因型 K 的狭义遗传力不同。对嵌合祖源比较其他树或 K；同时放入高度相似的 C 与 K 需检查可辨识性。','The variance fraction under tree covariance C differs from narrow-sense heritability under genomic K. Compare trees or K for mosaic ancestry; jointly fitting similar C and K requires identifiability checks.','La proportion sous C diffère de l’héritabilité au sens strict sous K. Comparez arbres ou K pour les ascendances mosaïques ; ajuster C et K similaires exige un contrôle d’identifiabilité.','La proporción bajo C difiere de la heredabilidad en sentido estricto bajo K. Compare árboles o K para ascendencias mosaico; combinar C y K similares exige comprobar identificabilidad.','C zuhaitz-kobariantzaren proportzioa eta K genomikoaren heredagarritasun hertsia desberdinak dira. Alderatu zuhaitzak edo K jatorri mosaikoetarako; C eta K antzekoak batera doitzeak identifikagarritasuna egiaztatzea eskatzen du.')],
    ['ml_tree','tree','dna',L('菌株树与基因组不一致性','Strain trees and genomic discordance','Arbres des souches et discordance génomique','Árboles de cepas y discordancia genómica','Andui-zuhaitzak eta desadostasun genomikoa'),L('群体树与不同基因组区段支持同一关系吗？','Do the population tree and genomic regions support the same relationships?','L’arbre de population et les régions génomiques soutiennent-ils les mêmes relations ?','¿Respaldan el árbol poblacional y las regiones genómicas las mismas relaciones?','Populazio-zuhaitzak eta eskualde genomikoek erlazio berak sostengatzen al dituzte?'),['dna','design'],['support'],['iqtree','raxml'],['iqtree','raxml','peter'],['evolution_context','reference_bias'],L('优先复用匹配的基因组树。SNP-only 比对需考虑 ascertainment correction；RNA 覆盖和等位丢失影响基因型。gCF/sCF 不单独判定重组原因。','Prefer a matched genomic tree. SNP-only alignments require consideration of ascertainment correction; RNA coverage and allelic dropout affect genotypes. gCF/sCF do not uniquely diagnose recombination.','Privilégiez un arbre génomique apparié. Les alignements SNP seuls exigent d’examiner la correction d’ascertainment ; couverture ARN et perte allélique affectent les génotypes. gCF/sCF n’identifient pas seuls la recombinaison.','Priorice un árbol genómico emparejado. Los alineamientos solo de SNP requieren considerar corrección de ascertainment; cobertura de ARN y pérdida alélica afectan genotipos. gCF/sCF no identifican por sí solos recombinación.','Lehenetsi parekatutako zuhaitz genomikoa. SNP hutsezko lerrokatzeek hautemate-zuzenketa aztertzea behar dute; RNA estaldurak eta alelo-galerak genotipoetan eragiten dute. gCF/sCFek ez dute birkonbinazioa bakarrik identifikatzen.')],
    ['bayesian_tree','tree','context',L('贝叶斯遗传树与时间校准','Bayesian trees and time calibration','Arbres bayésiens et calibration temporelle','Árboles bayesianos y calibración temporal','Zuhaitz bayestarrak eta denbora-kalibrazioa'),L('序列与独立时间资料支持怎样的历史区间？','What historical intervals do sequences and independent time evidence support?','Quels intervalles historiques les séquences et données temporelles indépendantes soutiennent-elles ?','¿Qué intervalos históricos respaldan las secuencias y la evidencia temporal independiente?','Zer tarte historiko sostengatzen dituzte sekuentziek eta denbora-ebidentzia independenteek?'),['dna','calibration','priors'],['dates'],['beast','revbayes'],['beast','revbayes'],['evolution_context'],L('绝对年代需要有效校准。分支遗传距离、细胞拟时序和 RNA velocity 是不同量；种间模型不能直接套用于重组菌株。','Absolute dates require valid calibration. Genetic branch distance, cell pseudotime and RNA velocity are different quantities; interspecies models do not transfer automatically to recombining strains.','Les dates absolues exigent une calibration valide. Distance génétique, pseudotemps et RNA velocity sont distincts ; les modèles interspécifiques ne se transfèrent pas automatiquement aux souches recombinantes.','Las fechas absolutas requieren calibración válida. Distancia genética, pseudotiempo y RNA velocity son magnitudes distintas; los modelos interespecíficos no se transfieren automáticamente a cepas recombinantes.','Data absolutuek baliozko kalibrazioa behar dute. Distantzia genetikoa, zelula-pseudodenbora eta RNA velocity magnitude desberdinak dira; espezie arteko ereduak ez dira zuzenean andui birkonbinanteetara eramaten.')],
    ['tree_atlas','tree','tree_required',L('遗传树与状态图谱联动','Linking genomic trees and state atlases','Relier arbres génomiques et atlas d’états','Vincular árboles genómicos y atlas de estados','Zuhaitz genomikoak eta egoera-atlasak lotzea'),L('噪音、状态比例和证据质量怎样分布在菌株背景中？','How do noise, state abundance and evidence quality vary across strains?','Comment bruit, abondance des états et qualité des preuves varient-ils entre souches ?','¿Cómo varían ruido, abundancia de estados y calidad de evidencia entre cepas?','Nola aldatzen dira zarata, egoera-ugaritasuna eta ebidentziaren kalitatea anduien artean?'),['tree','traits','design'],['overlays'],['ggtree','ete'],['ggtree','ete','peter'],['evolution_context','genotype_state'],L('树展示遗传关系，状态嵌入展示表达相似性，分别标注。ETE4 当前官方引用仍是 ETE3 论文；展示本身不推断祖先或因果。','Label genomic relationships and expression-state similarity separately. ETE4 currently requests the ETE3 paper citation; visualization itself infers neither ancestry nor causality.','Étiquetez séparément parenté génomique et similarité d’expression. ETE4 demande actuellement la citation ETE3 ; la visualisation n’infère ni ancêtres ni causalité.','Distinga parentesco genómico y similitud de expresión. ETE4 solicita actualmente citar ETE3; visualizar no infiere ancestros ni causalidad.','Etiketatu bereiz ahaidetasun genomikoa eta adierazpen-antzekotasuna. ETE4k ETE3 artikulua aipatzea eskatzen du; bistaratzeak ez du arbasorik edo kausalitaterik inferitzen.')],
    ['phylogenetic_signal','trait','tree_required',L('噪音的系统发育信号','Phylogenetic signal in noise','Signal phylogénétique du bruit','Señal filogenética del ruido','Zarataren seinale filogenetikoa'),L('亲缘接近的菌株是否具有更相似的条件化噪音？','Do related strains have more similar conditional noise?','Les souches apparentées ont-elles un bruit conditionnel plus similaire ?','¿Tienen las cepas emparentadas un ruido condicional más similar?','Ahaidetasun hurbileko anduiek baldintzapeko zarata antzekoagoa al dute?'),['traits','tree','covariates'],['signal'],['phytools'],['phytools','ives'],['evolution_context','mean_noise'],L('分别检验均值、条件化噪音和状态比例。phylosig 的 se 是性状估计标准误，不是细胞间标准差；λ/K 信号不直接等于遗传力。','Test mean, conditional noise and state abundance separately. phylosig se is trait-estimation SE, not cell-to-cell SD; λ/K signal is not directly heritability.','Testez séparément moyenne, bruit conditionnel et abondance des états. se de phylosig est l’erreur-type du caractère, pas l’écart-type entre cellules ; λ/K n’est pas directement l’héritabilité.','Pruebe por separado media, ruido condicional y abundancia de estados. se de phylosig es el error estándar del rasgo, no la DE entre células; λ/K no equivale directamente a heredabilidad.','Aztertu bereiz batezbestekoa, baldintzapeko zarata eta egoera-ugaritasuna. phylosig se ezaugarriaren estimazio-errorea da, ez zelulen arteko desbideratzea; λ/K ez da zuzenean heredagarritasuna.')],
    ['ancestral_states','trait','tree_required',L('祖先性状与不确定性','Ancestral traits and uncertainty','Caractères ancestraux et incertitude','Rasgos ancestrales e incertidumbre','Arbasoen ezaugarriak eta ziurgabetasuna'),L('给定树与演变模型，哪些祖先性状与观测相容？','Given a tree and model, which ancestral traits are compatible with observations?','Pour un arbre et un modèle donnés, quels caractères ancestraux concordent avec les observations ?','Dado un árbol y modelo, ¿qué rasgos ancestrales son compatibles con las observaciones?','Zuhaitz eta eredu jakin batekin, zer arbaso-ezaugarri dira bateragarriak behaketekin?'),['traits','tree','priors'],['ancestors'],['ancestors','revbayes'],['phytools','revbayes','ives'],['evolution_context'],L('fastAnc 使用 BM 假设；其区间不自动包含所有上游误差。推断节点与观测菌株分开展示，比较根、树与模型，不把当代菌株排成祖先序列。','fastAnc assumes BM; its intervals do not automatically include all upstream error. Distinguish inferred nodes from observed strains and compare roots, trees and models; contemporary strains are not an ancestor sequence.','fastAnc suppose BM ; ses intervalles n’incluent pas automatiquement toute erreur amont. Distinguez nœuds inférés et souches observées, comparez racines, arbres et modèles ; les souches actuelles ne forment pas une succession ancestrale.','fastAnc asume BM; sus intervalos no incluyen automáticamente todo error previo. Distinga nodos inferidos de cepas observadas y compare raíces, árboles y modelos; las cepas actuales no forman una secuencia ancestral.','fastAnc-ek BM suposatzen du; tarteek ez dute aurreko errore guztia automatikoki jasotzen. Bereizi inferitutako nodoak eta behatutako anduiak, eta alderatu erroak, zuhaitzak eta ereduak; egungo anduiak ez dira arbaso-sekuentzia.')],
    ['bm_ou','trait','tree_required',L('BM / OU 性状演变模型','BM / OU trait-evolution models','Modèles d’évolution BM / OU','Modelos de evolución BM / OU','BM / OU ezaugarrien eboluzio-ereduak'),L('哪些简洁演变模型能描述菌株间的噪音分布？','Which parsimonious evolutionary models describe noise across strains?','Quels modèles évolutifs parcimonieux décrivent le bruit entre souches ?','¿Qué modelos evolutivos parsimoniosos describen el ruido entre cepas?','Zein eboluzio-eredu sinplek deskribatzen dute anduien arteko zarata?'),['traits','tree','priors'],['rates'],['mvmorph','revbayes'],['mvmorph','revbayes','ives'],['evolution_context'],L('比较少量预先定义模型，传播测量误差并做模拟校准。OU 优于 BM 不单独证明稳定化选择；速率单位取决于分支长度单位。','Compare a small predefined model set, propagate measurement error and calibrate by simulation. Better OU fit does not alone establish stabilizing selection; rate units follow branch-length units.','Comparez peu de modèles prédéfinis, propagez l’erreur et calibrez par simulation. Un meilleur ajustement OU ne démontre pas seul une sélection stabilisante ; les taux dépendent des unités des branches.','Compare pocos modelos predefinidos, propague el error y calibre con simulaciones. Un mejor ajuste OU no demuestra por sí solo selección estabilizadora; las tasas dependen de las unidades de ramas.','Alderatu aurrez zehaztutako eredu gutxi, hedatu errorea eta kalibratu simulazioz. OU doikuntza hobeak ez du bakarrik hautespen egonkortzailea frogatzen; tasen unitateak adarren unitateen araberakoak dira.')],
    ['mean_noise_traits','trait','relatedness',L('均值—噪音多性状协同变化','Multivariate mean–noise change','Variation multivariée moyenne–bruit','Cambio multivariado media–ruido','Batezbesteko–zarata aldaketa multibariatua'),L('均值与噪音共享哪些遗传或系统发育协变？','Which genetic or phylogenetic covariation links mean and noise?','Quelle covariation génétique ou phylogénétique relie moyenne et bruit ?','¿Qué covariación genética o filogenética relaciona media y ruido?','Zer kobariazio genetiko edo filogenetikok lotzen ditu batezbestekoa eta zarata?'),['traits','design','inputK_or_C'],['multivariate'],['brms','mcmc','mvmorph'],['brms','mvmorph','duveau'],['shared_genetic_architecture','evolution_context'],L('按问题选择 K 遗传模型或树比较模型，不要求二者同时具备。均值与噪音共享估计误差；RNA 协变不是已测的蛋白适应度曲面。','Choose a genomic-K or tree-comparative model according to the question; both are not required together. Mean and noise share estimation error; RNA covariation is not a measured protein–fitness landscape.','Choisissez K ou un modèle comparatif sur arbre selon la question, sans exiger les deux. Moyenne et bruit partagent une erreur d’estimation ; leur covariation ARN n’est pas un paysage protéine–fitness mesuré.','Elija K o un modelo comparativo de árbol según la pregunta; no se requieren ambos. Media y ruido comparten error de estimación; su covariación de ARN no es un paisaje proteína–aptitud medido.','Hautatu K genomikoa edo zuhaitz-konparazio eredua galderaren arabera; ez dira biak batera behar. Batezbestekoak eta zaratak estimazio-errorea partekatzen dute; RNA kobariazioa ez da neurtutako proteina–egokitasun paisaia.')],
    ['plasticity_convergence','trait','context',L('可塑性、趋同与基因复制','Plasticity, convergence and duplication','Plasticité, convergence et duplication','Plasticidad, convergencia y duplicación','Plastikotasuna, konbergentzia eta bikoizketa'),L('跨环境或独立遗传背景中，哪些分布变化重复出现？','Which distribution shifts recur across environments or independent genetic histories?','Quels changements de distribution se répètent entre environnements ou histoires indépendantes ?','¿Qué cambios de distribución se repiten entre entornos o historias independientes?','Zer banaketa-aldaketa errepikatzen dira inguruneetan edo historia genetiko independenteetan?'),['traits','design','context','lineageTree'],['response','multivariate'],['brms','mvmorph'],['peter','brms','mvmorph'],['evolution_context','genotype_state'],L('可塑性需同菌株跨真实环境；趋同需独立起源及比较证据；复制分析需 DNA 剂量/同源关系。培养条件与生态来源分开编码，单一 RNA 快照不能证明适应性或风险分散。','Plasticity requires the same strains across measured environments; convergence needs independent origins and comparative evidence; duplication needs DNA dosage/homology. Separate culture conditions from ecological origin. One RNA snapshot cannot establish adaptation or bet hedging.','La plasticité exige les mêmes souches dans plusieurs environnements mesurés ; la convergence, des origines indépendantes ; la duplication, dosage ADN/homologie. Séparez culture et origine écologique. Un instantané ARN ne démontre ni adaptation ni bet hedging.','La plasticidad requiere las mismas cepas en entornos medidos; la convergencia, orígenes independientes; la duplicación, dosis de ADN/homología. Separe cultivo y origen ecológico. Una instantánea de ARN no demuestra adaptación ni bet hedging.','Plastikotasunak andui berak neurtutako inguruneetan behar ditu; konbergentziak jatorri independenteak; bikoizketak DNA dosia/homologia. Bereizi kultiboa eta jatorri ekologikoa. RNA argazki bakarrak ez du moldapena edo arrisku-banaketa frogatzen.')],
    ['population_scenarios','simulation','model',L('群体与后验模拟情景','Population and posterior simulation scenarios','Scénarios de population et simulations postérieures','Escenarios poblacionales y simulaciones posteriores','Populazio- eta simulazio posteriorreko eszenarioak'),L('重组、抽样或指定选择机制能产生观察到的模式吗？','Can recombination, sampling or a specified selection model produce the observed pattern?','La recombinaison, l’échantillonnage ou une sélection spécifiée peuvent-ils produire le motif observé ?','¿Pueden recombinación, muestreo o un modelo de selección especificado producir el patrón observado?','Birkonbinazioak, laginketak edo zehaztutako hautespen-ereduak behatutako eredua sor al dezakete?'),['scenarios','priors','design'],['simulation'],['slim','msprime','sbc'],['slim','msprime','sbc'],['mechanistic_noise_benchmark','noise_power','evolution_context'],L('SLiM/msprime 模拟遗传群体；RNA 计数需另建观测模型。后验预测需要已拟合后验，情景模拟不需要假称已拟合。适应度或实验进化结论另需真实测量与谱系记录。','SLiM/msprime simulate genetic populations; RNA counts require an observation model. Posterior prediction needs a fitted posterior, whereas scenario simulation does not imply a fit. Fitness or experimental-evolution conclusions require measurements and lineage records.','SLiM/msprime simulent des populations génétiques ; les comptages ARN exigent un modèle d’observation. La prédiction postérieure exige un modèle ajusté, contrairement à un scénario. Fitness et évolution expérimentale nécessitent mesures et lignées.','SLiM/msprime simulan poblaciones genéticas; los recuentos de ARN requieren un modelo de observación. La predicción posterior exige un ajuste; un escenario no lo implica. Aptitud y evolución experimental requieren medidas y linajes.','SLiM/msprime-k populazio genetikoak simulatzen dituzte; RNA zenbaketek behaketa-eredua behar dute. Iragarpen posteriorrak doitutako posteriorra behar du; eszenarioak ez du doikuntzarik esan nahi. Egokitasun eta eboluzio esperimentalaren ondorioek neurketak eta leinuak behar dituzte.')]
  ];
  const ROWS=RAW.map(([id,family,feasibility,title,question,inputs,metrics,tools,papers,routeIds,interpretation])=>({id,family,feasibility,title,question,inputs:inputs.map(k=>INPUTS[k]),metrics:metrics.map(k=>METRICS[k]),tools:tools.map(k=>TOOLS[k]),papers:papers.map(k=>({...PAPERS[k],url:'https://doi.org/'+PAPERS[k].doi})),routeIds,interpretation,sourceUrls:[...new Set([...tools.map(k=>TOOLS[k].url),...papers.map(k=>'https://doi.org/'+PAPERS[k].doi)])]}));
  const state={query:'',family:'all',open:new Set(),customizeOpen:new Set(),implementationOpen:new Set(),variants:{},mutating:false};
  const A=()=>window.YV_APP,D=()=>A()?.data?.()||{},B=()=>window.YV_BUILDER,language=()=>LANGS.includes(A()?.prefs?.().language)?A().prefs().language:'en',tx=o=>typeof o==='string'?o:o?.[language()]||o?.en||'',T=k=>tx(COPY[k]);
  const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const normalized=v=>String(v??'').normalize('NFKD').replace(/\p{M}/gu,'').toLowerCase().trim();
  const rows=()=>{const all=[...ROWS,...(D().projects?.evolutionGuides||[]),...(window.YV_EVOLUTION_V30_RECORDS||[])];return all.filter((r,i)=>r?.id&&all.findIndex(x=>x.id===r.id)===i);};
  const queried=()=>{const terms=normalized(state.query).split(/\s+/).filter(Boolean);return rows().filter(r=>{const index=normalized(JSON.stringify([r.id,r.title,r.question,r.inputs,r.metrics,r.interpretation,r.tools,r.papers]));return terms.every(q=>index.includes(q));});};
  const results=()=>queried().filter(r=>state.family==='all'||r.family===state.family);
  const routeTitle=r=>{const val=A()?.tx?.(r.title||r.name)||r.title||r.name;return typeof val==='object'?tx(val):language()!=='zh'&&/[\u3400-\u9fff]/u.test(val)?r.titleEn||r.nameEn||r.id:String(val||r.titleEn||r.nameEn||r.id);};
  const definition=id=>(D().projects?.evolutionRecipes||[]).find(r=>r.id===id);
  const recipeId=id=>'evolution:'+id;
  function snapshot(){const plan=B()?.getPlan?.()||{},review=B()?.analysisReview?.()||{selections:[]};return {plan,reviews:new Map((review.selections||[]).map(r=>[r.id,r])),saved:new Map((plan.analysisSelections||[]).map(r=>[r.id,r]))};}
  const selected=s=>rows().filter(r=>s.saved.has(recipeId(r.id))).map(r=>r.id);
  function variantFor(id,s){const def=definition(id),saved=s.saved.get(recipeId(id));if(saved&&!saved.variantId)return null;return def?.variants?.find(v=>v.id===(saved?.variantId||state.variants[id]||def.defaultVariant))||(!saved?def?.variants?.[0]:null);}
  function recipeFor(id,s){const variant=variantFor(id,s);return variant?.recipe?{...variant.recipe,id:recipeId(id),variantId:variant.id}:null;}
  const toolRecord=id=>D().workflow?.tools?.find(t=>t.id===id),metricRecord=id=>D().workflow?.metrics?.find(m=>m.id===id);
  const named=(kind,r)=>{const value=A()?.field?.(kind,r,'name');return value&&typeof value==='string'&&!((language()!=='zh')&&/[\u3400-\u9fff]/u.test(value))?value:routeTitle(r);};
  const evidenceValue=(s,id,requirementId)=>{const value=s.plan.analysisInputEvidence?.[recipeId(id)]?.[requirementId];return typeof value==='string'?value:'';};
  const inputTitle=id=>{const item=D().categories?.dataRequirements?.find(x=>x.id===id);return item?routeTitle(item):id;};
  const toolLink=id=>{const t=toolRecord(id);return t?`<button type="button" data-ev29-tool="${E(id)}" aria-label="${E(T('toolDetail')+' · '+named('tools',t))}">${E(named('tools',t))}</button>`:`<span>${E(id)}</span>`;};
  function effective(r,s){const saved=s.saved.get(recipeId(r.id)),recipe=saved||recipeFor(r.id,s)||{},review=s.reviews.get(recipeId(r.id)),preview=!saved&&window.YV_INPUTS?.analysisContext?window.YV_INPUTS.analysisContext({...s.plan,analysisSelections:[recipe],tools:[...new Set([...(s.plan.tools||[]),...(recipe.toolIds||[])])],metrics:[...new Set([...(s.plan.metrics||[]),...(recipe.metricIds||[])])],toolBranches:{...recipe.toolBranches,...s.plan.toolBranches}},D()).selections[0]:null;return {saved,recipe,review,toolIds:review?.toolIds||preview?.toolIds||recipe.toolIds||[],metricIds:review?.metricIds||preview?.metricIds||recipe.metricIds||[],requiredData:review?.requiredData||preview?.requiredData||recipe.requiredData||[],additionalRequirements:review?.additionalRequirements||recipe.additionalRequirements||[]};}
  const pendingInputs=e=>(e.review?.missingData?.length||0)+(e.review?.issues||[]).filter(i=>i.kind==='analysis-external-input-pending').length;
  function planSummary(r,s){const e=effective(r,s),ready=!!B()?.setAnalysis&&!!recipeFor(r.id,s),status=e.saved?(e.review?.status||'decision-pending'):ready?'autoReady':'unavailable';return `<div class="ev29-association" data-ev29-association="${E(r.id)}"><div class="ev29-associated-tools">${e.toolIds.map(toolLink).join('')}</div><p class="ev29-counts">${e.toolIds.length} ${E(T('toolCount'))} · ${e.metricIds.length} ${E(T('metricCount'))} · ${e.requiredData.length+e.additionalRequirements.length} ${E(T('inputCount'))}</p><p class="ev29-plan-status" data-status="${E(status)}">${E(T(status))}${pendingInputs(e)?` · ${pendingInputs(e)} ${E(T('missingInputs'))}`:''}</p>${e.review?.overrides&&(e.review.overrides.excludedToolIds.length||e.review.overrides.excludedMetricIds.length||e.review.overrides.branches.length)?`<p class="ev29-override-note">${E(T('overridden'))}</p>`:''}</div>`;}
  function modelPanel(r,e){const model=e.recipe.modelSpecification;if(!model)return '';const notes=Array.isArray(model.notes)?model.notes.map(tx).filter(Boolean):[tx(model.notes)].filter(Boolean);return `<section class="ev29-model"><h4>${E(T('modelSpecification'))}</h4>${model.expression?`<code class="ev29-model-expression">${E(model.expression)}</code>`:''}${model.entrypoint||notes.length?`<details class="ev29-implementation" data-ev29-implementation="${E(r.id)}" ${state.implementationOpen.has(r.id)?'open':''}><summary>${E(T('modelImplementation'))}</summary>${model.entrypoint?`<pre><code>${E(model.entrypoint)}</code></pre>`:''}${notes.map(note=>`<p>${E(note)}</p>`).join('')}${model.sourceUrls?.length?`<ul>${model.sourceUrls.map(url=>`<li><a href="${E(url)}" target="_blank" rel="noopener noreferrer">${E(url)}</a></li>`).join('')}</ul>`:''}</details>`:''}</section>`;}
  function customize(r,s){const e=effective(r,s),def=definition(r.id),variant=variantFor(r.id,s),disabled=e.saved?'':'disabled',hasOverrides=e.review?.overrides&&(e.review.overrides.excludedToolIds.length||e.review.overrides.excludedMetricIds.length||e.review.overrides.branches.length);return `<details class="ev29-customize" data-ev29-customize="${E(r.id)}" ${state.customizeOpen.has(r.id)?'open':''}><summary>${E(T('customize'))}</summary><div class="ev29-detail-body">${def?.variants?.length>1?`<label class="ev29-field" for="ev29-variant-${E(r.id)}">${E(T('variant'))}<select id="ev29-variant-${E(r.id)}" data-ev29-variant="${E(r.id)}">${!variant?`<option value="">${E(T('savedVariant'))}</option>`:''}${def.variants.map(v=>`<option value="${E(v.id)}" ${v.id===variant?.id?'selected':''}>${E(tx(v.title))}</option>`).join('')}</select></label>`:''}${!e.saved?`<p class="ev29-manual-hint">${E(T('selectFirst'))}</p>`:''}${modelPanel(r,e)}<section><h4>${E(T('linkedTools'))}</h4><ul class="ev29-choice-list">${e.toolIds.map(id=>{const tool=toolRecord(id),branches=tool?window.YV_INPUTS?.toolContract?.(tool)?.branches||[]:[];return `<li><label><input id="ev29-tool-${E(r.id)}-${E(id)}" type="checkbox" data-ev29-tool-choice="${E(r.id)}" data-value="${E(id)}" ${(!e.saved||s.plan.tools?.includes(id))?'checked':''} ${!tool?'disabled':disabled}>${E(tool?named('tools',tool):id)}</label>${tool?`<button type="button" data-ev29-tool="${E(id)}" aria-label="${E(T('toolDetail')+' · '+named('tools',tool))}">${E(T('toolDetail'))}</button>`:''}${branches.length?`<label class="ev29-field" for="ev29-branch-${E(r.id)}-${E(id)}">${E(T('branch'))}<select id="ev29-branch-${E(r.id)}-${E(id)}" data-ev29-branch="${E(r.id)}" data-value="${E(id)}" ${disabled}><option value="">${E(T('chooseBranch'))}</option>${s.plan.toolBranches?.[id]&&!branches.some(b=>b.id===s.plan.toolBranches[id])?`<option value="${E(s.plan.toolBranches[id])}" selected>${E(s.plan.toolBranches[id])} · ${E(T('savedVariant'))}</option>`:''}${branches.map(b=>`<option value="${E(b.id)}" ${s.plan.toolBranches?.[id]===b.id?'selected':''}>${E(tx(b.title)||b.id)}</option>`).join('')}</select></label>`:''}</li>`;}).join('')}</ul></section><section><h4>${E(T('linkedMetrics'))}</h4><ul class="ev29-choice-list">${e.metricIds.map(id=>`<li><label><input id="ev29-metric-${E(r.id)}-${E(id)}" type="checkbox" data-ev29-metric-choice="${E(r.id)}" data-value="${E(id)}" ${(!e.saved||s.plan.metrics?.includes(id))?'checked':''} ${!metricRecord(id)?'disabled':disabled}>${E(metricRecord(id)?named('metrics',metricRecord(id)):id)}</label></li>`).join('')}</ul></section><section><h4>${E(T('inputCount'))}</h4><ul class="ev29-input-list">${e.requiredData.map(id=>`<li><span>${E(inputTitle(id))}</span><small>${E(T(s.plan.availableData?.includes(id)?'declared':'prepare'))}</small></li>`).join('')}${e.additionalRequirements.map(item=>`<li class="ev29-extra-input"><div><span>${E(tx(item.label)||item.id)}</span><small>${E(T(evidenceValue(s,r.id,item.id).trim()?'sourceRecorded':'prepare'))}</small></div><label class="ev29-field" for="ev29-evidence-${E(r.id)}-${E(item.id)}">${E(T('sourceField'))}<input type="text" id="ev29-evidence-${E(r.id)}-${E(item.id)}" data-ev29-evidence="${E(r.id)}" data-value="${E(item.id)}" value="${E(evidenceValue(s,r.id,item.id))}" autocomplete="off" ${disabled}></label></li>`).join('')}</ul></section>${e.review?.issues?.some(i=>i.kind!=='analysis-external-input-pending')?`<section><h4>${E(T('decisions'))}</h4><ul class="ev29-issues">${e.review.issues.filter(i=>i.kind!=='analysis-external-input-pending').map(issue=>`<li>${E(T(issue.kind)||issue.kind)}${issue.label?`: ${E(tx(issue.label))}`:issue.toolId?`: ${E(toolRecord(issue.toolId)?routeTitle(toolRecord(issue.toolId)):issue.toolId)}`:issue.inputId?`: ${E(inputTitle(issue.inputId))}`:''}</li>`).join('')}</ul></section>`:''}<div class="ev29-manual-actions">${e.saved?`<button type="button" id="ev29-restore-${E(r.id)}" data-ev29-restore="${E(r.id)}" ${hasOverrides?'':'disabled'}>${E(T('restore'))}</button>`:''}<a href="#workbench?stage=scope">${E(T('openPlan'))}</a></div></div></details>`;}
  function card(r,s){const routes=r.routeIds.map(id=>D().projects?.projects?.find(x=>x.id===id)).filter(Boolean),saved=s.saved.has(recipeId(r.id)),ready=!!B()?.setAnalysis&&(saved||!!recipeFor(r.id,s));return `<article class="ev29-card" data-ev29-card="${E(r.id)}"><header><span class="ev29-family">${E(T(r.family))}</span><label class="ev29-select"><input id="ev29-select-${E(r.id)}" type="checkbox" data-ev29-select="${E(r.id)}" ${saved?'checked':''} ${ready?'':'disabled'} aria-label="${E(T('select')+' · '+tx(r.title))}"><span>${E(T('select'))}</span></label></header><h3>${E(tx(r.title))}</h3><p class="ev29-question">${E(tx(r.question))}</p><span class="ev29-requirement">${E(T(r.feasibility))}</span>${planSummary(r,s)}${customize(r,s)}<details data-ev29-details="${E(r.id)}" ${state.open.has(r.id)?'open':''}><summary>${E(T('details'))}</summary><div class="ev29-detail-body"><section><h4>${E(T('inputs'))}</h4><ul>${r.inputs.map(v=>`<li>${E(tx(v))}</li>`).join('')}</ul></section><section><h4>${E(T('metrics'))}</h4><ul>${r.metrics.map(v=>`<li>${E(tx(v))}</li>`).join('')}</ul></section><section><h4>${E(T('interpretation'))}</h4><p>${E(tx(r.interpretation))}</p></section><section><h4>${E(T('tools'))}</h4><ul class="ev29-tools">${r.tools.map(t=>`<li>${t.id&&toolRecord(t.id)?toolLink(t.id):`<strong>${E(t.name)}</strong>`}<a href="${E(t.url)}" target="_blank" rel="noopener noreferrer">${E(T('docs'))}<span aria-hidden="true"> ↗</span></a></li>`).join('')}</ul></section><section><h4>${E(T('papers'))}</h4><ul class="ev29-papers">${r.papers.map(p=>`<li><a href="${E(p.url)}" target="_blank" rel="noopener noreferrer">${E(p.title)} (${p.year})<span aria-hidden="true"> ↗</span></a></li>`).join('')}</ul></section></div></details>${routes.length?`<footer><span>${E(T('routes'))}</span>${routes.map(p=>`<button type="button" data-ev29-route="${E(p.id)}">${E(routeTitle(p))}<span aria-hidden="true"> ↗</span></button>`).join('')}</footer>`:''}</article>`;}
  const status=s=>`${results().length} / ${rows().length} ${T('matches')} · ${selected(s).length} ${T('selected')}`;
  const resultHTML=s=>results().length?results().map(r=>card(r,s)).join(''):`<div class="ev29-empty"><h3>${E(T('empty'))}</h3><p>${E(T('emptyHelp'))}</p><button type="button" data-ev29-reset>${E(T('reset'))}</button></div>`;
  function panel(){const q=queried(),s=snapshot(),count=selected(s).length;return `<section class="ev29" id="evolution-catalogue-v29" aria-labelledby="ev29-title"><header class="ev29-heading"><h2 id="ev29-title">${E(T('title'))}</h2><p>${E(T('intro'))}</p></header><details class="ev29-model-map"><summary>${E(T('modelMap'))}</summary><ol>${['model1','model2','model3','model4'].map(k=>`<li>${E(T(k))}</li>`).join('')}</ol></details><div class="ev29-toolbar"><label for="ev29-query">${E(T('search'))}<input id="ev29-query" type="search" data-ev29-query value="${E(state.query)}" autocomplete="off"></label><button type="button" data-ev29-reset>${E(T('reset'))}</button></div><nav class="ev29-filters" aria-label="${E(T('filters'))}">${['all',...FAMILIES].map(f=>`<button type="button" data-ev29-family="${f}" aria-pressed="${state.family===f}" aria-controls="ev29-results"><span>${E(T(f))}</span><small data-ev29-count="${f}">${f==='all'?q.length:q.filter(r=>r.family===f).length}</small></button>`).join('')}</nav><div class="ev29-selection-bar"><p id="ev29-status" role="status" aria-live="polite" aria-atomic="true">${E(status(s))}</p><div><a class="ev29-plan-link" href="#workbench?stage=scope">${E(T('openPlan'))}</a><button type="button" data-ev29-clear ${count?'':'disabled'}>${E(T('clear'))}</button><button type="button" data-ev29-export ${count?'':'disabled'}>${E(T('export'))}</button></div></div><p class="ev29-note">${E(T('note'))}</p><p id="ev29-message" role="status" aria-live="polite"></p><div id="ev29-results" class="ev29-grid">${resultHTML(s)}</div></section>`;}
  function refresh(focusId){const root=document.getElementById('evolution-catalogue-v29');if(!root)return;const active=focusId||document.activeElement?.id,s=snapshot(),result=root.querySelector('#ev29-results');if(result)result.innerHTML=resultHTML(s);const q=queried();root.querySelectorAll('[data-ev29-family]').forEach(b=>{b.setAttribute('aria-pressed',String(state.family===b.dataset.ev29Family));const c=b.querySelector('[data-ev29-count]');if(c)c.textContent=b.dataset.ev29Family==='all'?q.length:q.filter(r=>r.family===b.dataset.ev29Family).length;});const summary=root.querySelector('#ev29-status');if(summary)summary.textContent=status(s);root.querySelectorAll('[data-ev29-export],[data-ev29-clear]').forEach(x=>{x.disabled=!selected(s).length;});if(active?.startsWith('ev29-'))document.getElementById(active)?.focus({preventScroll:true});}
  function perform(fn,focusId){state.mutating=true;try{fn();}finally{state.mutating=false;refresh(focusId);}}
  function exportSelection(){const s=snapshot();return {schema:'yeastvar1011.evolution-analysis-selection',version:2,createdAt:new Date().toISOString(),language:language(),purpose:'research_planning',executionStatus:'not_executed',mainPlanLinked:true,selectionScope:'all_selected_including_hidden_by_filters',methods:rows().filter(r=>s.saved.has(recipeId(r.id))).map(r=>({...r,recipe:s.saved.get(recipeId(r.id)),inputEvidence:s.plan.analysisInputEvidence?.[recipeId(r.id)]||{},planReview:s.reviews.get(recipeId(r.id))||null,display:{title:tx(r.title),question:tx(r.question),inputs:r.inputs.map(tx),metrics:r.metrics.map(tx),interpretation:tx(r.interpretation)}}))};}
  function download(){if(!selected(snapshot()).length)return;const blob=new Blob([JSON.stringify(exportSelection(),null,2)],{type:'application/json;charset=utf-8'}),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download='YeastVar1011-evolution-analysis-selection.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),1000);const message=document.getElementById('ev29-message');if(message)message.textContent=T('exported');}
  document.addEventListener('input',event=>{if(event.target?.dataset?.ev29Query===undefined)return;state.query=event.target.value;refresh();});
  document.addEventListener('change',event=>{const el=event.target,d=el?.dataset||{},id=d.ev29Select||d.ev29Variant||d.ev29ToolChoice||d.ev29MetricChoice||d.ev29Branch||d.ev29Evidence;if(!rows().some(r=>r.id===id))return;const s=snapshot();if(d.ev29Select){const recipe=s.saved.get(recipeId(id))||recipeFor(id,s);if(recipe&&B()?.setAnalysis)perform(()=>B().setAnalysis(recipe,el.checked),el.id);return;}if(d.ev29Variant){const variant=definition(id)?.variants?.find(v=>v.id===el.value);if(!variant)return;state.variants[id]=variant.id;if(s.saved.has(recipeId(id)))perform(()=>B()?.setAnalysis?.({...variant.recipe,id:recipeId(id),variantId:variant.id},true),el.id);else refresh(el.id);return;}if(!s.saved.has(recipeId(id)))return;const effectiveRow=effective(rows().find(r=>r.id===id),s);if(d.ev29Evidence&&effectiveRow.additionalRequirements.some(x=>x.id===d.value))perform(()=>B()?.setAnalysisEvidence?.(recipeId(id),d.value,el.value),el.id);if(d.ev29ToolChoice&&effectiveRow.toolIds.includes(d.value))perform(()=>B()?.toggleTool?.(d.value,el.checked),el.id);if(d.ev29MetricChoice&&effectiveRow.metricIds.includes(d.value))perform(()=>B()?.toggleMetric?.(d.value,el.checked),el.id);if(d.ev29Branch&&effectiveRow.toolIds.includes(d.value))perform(()=>B()?.setToolBranch?.(d.value,el.value),el.id);});
  document.addEventListener('click',event=>{const b=event.target.closest?.('[data-ev29-family],[data-ev29-reset],[data-ev29-clear],[data-ev29-export],[data-ev29-route],[data-ev29-tool],[data-ev29-restore]');if(!b)return;if(b.dataset.ev29Family&&['all',...FAMILIES].includes(b.dataset.ev29Family)){state.family=b.dataset.ev29Family;refresh();return;}if(b.hasAttribute('data-ev29-reset')){state.query='';state.family='all';const q=document.getElementById('ev29-query');if(q)q.value='';refresh();q?.focus({preventScroll:true});return;}if(b.hasAttribute('data-ev29-clear')){const s=snapshot();perform(()=>{const ids=selected(s).map(recipeId);if(B()?.removeAnalyses)B().removeAnalyses(ids);else ids.forEach(id=>B()?.setAnalysis?.(s.saved.get(id),false));});document.getElementById('ev29-query')?.focus({preventScroll:true});return;}if(b.hasAttribute('data-ev29-export')){download();return;}if(b.dataset.ev29Restore&&snapshot().saved.has(recipeId(b.dataset.ev29Restore))){perform(()=>B()?.resetAnalysisOverrides?.(recipeId(b.dataset.ev29Restore)),b.id);return;}if(b.dataset.ev29Route&&D().projects?.projects?.some(p=>p.id===b.dataset.ev29Route))A()?.openRecord?.('project',b.dataset.ev29Route);if(b.dataset.ev29Tool&&toolRecord(b.dataset.ev29Tool))A()?.openRecord?.('tool',b.dataset.ev29Tool);});
  document.addEventListener('toggle',event=>{const detailId=event.target?.dataset?.ev29Details,customId=event.target?.dataset?.ev29Customize,implementationId=event.target?.dataset?.ev29Implementation,id=detailId||customId||implementationId;if(!id)return;const set=detailId?state.open:customId?state.customizeOpen:state.implementationOpen;if(event.target.open)set.add(id);else if(event.target.isConnected!==false)set.delete(id);},true);
  window.addEventListener?.('yv:planchange',()=>{if(!state.mutating)refresh();});
  window.YV_EVOLUTION_CATALOGUE={panel,records:()=>JSON.parse(JSON.stringify(rows())),results:()=>results().map(r=>r.id),getState:()=>({query:state.query,family:state.family,selected:selected(snapshot())}),exportSelection};
